import math

class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        # Step 1: Generate primes up to n using Sieve of Eratosthenes
        # Since x + y = n and x, y >= 1, the largest possible prime we need to check is n-1 (if the other prime is 1, but 1 is not prime).
        # The largest possible prime we need to check is n itself (if the other prime is 0, which is not allowed).
        # Since x <= y and x+y=n, the maximum value for x or y is n.
        # However, since x and y must be prime, the maximum value we need to sieve up to is n.

        is_prime = [True] * (n + 1)
        if n >= 0:
            is_prime[0] = False
        if n >= 1:
            is_prime[1] = False

        for p in range(2, int(math.sqrt(n)) + 1):
            if is_prime[p]:
                for multiple in range(p * p, n + 1, p):
                    is_prime[multiple] = False

        # Step 2: Find all prime pairs [x, y] such that x + y = n and x <= y
        prime_pairs = []

        # We iterate through possible values of x, starting from 1 up to n // 2.
        # Since x must be prime, we only need to check values of x that are prime.
        # The loop for x should go up to n // 2 because we require x <= y, and x + y = n.
        for x in range(2, n // 2 + 1):
            if is_prime[x]:
                y = n - x
                # Check if y is prime and if y satisfies the condition y >= x (which is guaranteed by x <= n // 2)
                if is_prime[y]:
                    prime_pairs.append([x, y])

        # Step 3: Return the list of prime pairs. The iteration order of x ensures the list is sorted by x_i.
        return prime_pairs

