class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
        n = len(nums)
        max_val = -float('inf')
        found_positive = False

        # Iterate through all possible triplets (i, j, k) such that i < j < k
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    # Calculate the value of the triplet
                    triplet_value = (nums[i] - nums[j]) * nums[k]

                    # Update the maximum value found
                    if triplet_value > max_val:
                        max_val = triplet_value

                    # Check if any triplet has a positive value
                    if triplet_value > 0:
                        found_positive = True

        # If no positive value was found, return 0, otherwise return the maximum value
        if not found_positive:
            return 0
        else:
            # Since we initialized max_val to -inf, if found_positive is True, 
            # max_val must be at least the largest positive value found.
            return max_val

