    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        n = len(s)

        # Step 1: Find the length of the shortest beautiful substring (len)
        min_len = float('inf')

        for i in range(n):
            count_ones = 0
            for j in range(i, n):
                # Substring s[i:j+1]
                if s[j] == '1':
                    count_ones += 1

                if count_ones == k:
                    current_len = j - i + 1
                    min_len = min(min_len, current_len)

        # If no beautiful substring exists, return ""
        if min_len == float('inf'):
            return ""

        # Step 2: Find the lexicographically smallest beautiful substring of length min_len

        best_substring = ""

        # Initialize best_substring to a lexicographically large string of length min_len
        # Since the alphabet is {'0', '1'}, the largest possible string is all '1's.
        best_substring = '1' * (min_len + 1) # Initialize to something larger than any valid candidate

        found_candidate = False

        for i in range(n):
            for j in range(i + min_len - 1, n):
                # Check substring s[i:j+1] of length min_len
                substring = s[i:i + min_len]

                # Check if this substring is beautiful (has exactly k ones)
                if substring.count('1') == k:
                    if not found_candidate:
                        best_substring = substring
                        found_candidate = True
                    else:
                        # Compare lexicographically
                        # If substring is lexicographically smaller than best_substring, update
                        if substring < best_substring:
