class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        min_sum = float('inf')
        found_mountain = False

        # Iterate through all possible middle elements (j)
        # j must be at least 1 and at most n-2 to allow for i and k
        for j in range(1, n - 1):
            # Iterate through all possible left elements (i)
            # i must be less than j
            for i in range(j):
                # Check the first condition for the peak: nums[i] < nums[j]
                if nums[i] < nums[j]:
                    # Iterate through all possible right elements (k)
                    # k must be greater than j
                    for k in range(j + 1, n):
                        # Check the second condition for the peak: nums[k] < nums[j]
                        if nums[k] < nums[j]:
                            # If both conditions are met, (i, j, k) is a mountain triplet
                            current_sum = nums[i] + nums[j] + nums[k]
                            min_sum = min(min_sum, current_sum)
                            found_mountain = True

        if found_mountain:
            return min_sum
        else:
            return -1

